package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.NoClass;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.jsontype.*;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class StdTypeResolverBuilder_typeProperty_TriageGen2Test {

    @Mock
    private TypeIdResolver mockIdResolver;

    @Test
    public void testTypeProperty_WithValidString() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        builder.init(JsonTypeInfo.Id.NAME, mockIdResolver);

        String expectedProp = "customProperty";
        StdTypeResolverBuilder result = builder.typeProperty(expectedProp);

        assertEquals(builder, result);
        assertEquals(expectedProp, builder.getTypeProperty());
    }

    @Test
    public void testTypeProperty_WithNullString() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        String defaultProp = "defaultProp";

        // Mocking the behavior of the internal _idType to return a default property name
        // Since _idType is set via init(), we use a resolver that provides the default
        when(mockIdResolver.getTypeId(null, null)).thenReturn(null); // dummy call
        // In Jackson, the default property name comes from the IdType (e.g., JsonTypeInfo.Id.NAME)
        // We simulate the logic by ensuring the builder uses the default when null is passed.

        builder.init(JsonTypeInfo.Id.NAME, mockIdResolver);
        // For JsonTypeInfo.Id.NAME, the default property name is usually "@type"
        String expectedDefault = JsonTypeInfo.Id.NAME.getDefaultPropertyName();

        builder.typeProperty(null);

        assertEquals(expectedDefault, builder.getTypeProperty());
    }

    @Test
    public void testTypeProperty_WithEmptyString() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        builder.init(JsonTypeInfo.Id.NAME, mockIdResolver);

        String expectedDefault = JsonTypeInfo.Id.NAME.getDefaultPropertyName();

        builder.typeProperty("");

        assertEquals(expectedDefault, builder.getTypeProperty());
    }
}
